/**
 * @summary Preview export data before download (first 100 rows)
 */
export const getPreviewExportUrl = (params: PreviewExportParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/exports/preview?${stringifiedParams}`
    : `/api/exports/preview`;
};

export const previewExport = async (
  params: PreviewExportParams,
  options?: RequestInit,
): Promise<PreviewExport200> => {
  return customFetch<PreviewExport200>(getPreviewExportUrl(params), {
    ...options,
    method: 'GET',
  });
};

export const getPreviewExportQueryKey = (params?: PreviewExportParams) => {
  return [`/api/exports/preview`, ...(params ? [params] : [])] as const;
};

export const getPreviewExportQueryOptions = <
  TData = Awaited<ReturnType<typeof previewExport>>,
  TError = ErrorType<UnauthorizedResponse>,
>(
  params: PreviewExportParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof previewExport>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getPreviewExportQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof previewExport>>> = ({
    signal,
  }) => previewExport(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof previewExport>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

