/**
 * @summary List available destination objects for a connector type
 */
export const getListConduitDestinationObjectsUrl = (
  destination: string,
  params?: ListConduitDestinationObjectsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/conduit/destinations/${destination}/objects?${stringifiedParams}`
    : `/api/conduit/destinations/${destination}/objects`;
};

